// Request ciphertexts generated by primary quii-helper talk/packets.py with
// synthetic key k*32 and fixed Unix time 1700000000.125, independently of Go.
func TestTalkNativeCommandFixtures(t *testing.T) {
	c := testCodec(t)
	now := time.Unix(1700000000, 125000000)
	cases := []struct {
		name string
		h    [32]byte
		body []byte
		want string
	}{
		{"send", talkRequest(65535, true, 4, now), nil, "d30b1cfd76675cd2a6bc775db1427702c06148d74ee8934af3ebf712364a94fac6052b8c362c8283832271fde5ed234d89d78da51ea9cde18220f189d5d005a7"},
		{"receive", talkRequest(65535, false, 5, now), nil, "d4947be777f92c4b06beef2236e3c00b67dca8a403a8a21cb9e34166e36c39e4afbfa5bae6b9807fc82140947a60647223e0f32f7a9b1b645d29031c7288962c"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := c.EncodeCommand(tc.h, tc.body)
			if err != nil || hex.EncodeToString(got) != tc.want {
				t.Fatalf("packet fixture mismatch: %v", err)
			}
		})
	}
}
func TestTalkNativeAudioFixtures(t *testing.T) {
	for _, full := range []bool{false, true} {
		c := testCodec(t)
		s := &TalkSession{codec: c, audioCodec: 4, fullPacket: full}
		now := time.Unix(1700000000, 125000000)
		want := "68455abf06c3c7d1f6dcea333dad087806175aa35cf890afd93542b8460ced20"
		if full {
			s.audioCodec = 5
			now = time.Date(2026, 10, 27, 12, 34, 56, 125000000, time.UTC)
			want = "efb7f0421dbf3d0b8cc9e5a714e5048f860b5dadef4b9c78e9e5dce1b07df0c7"
		}
		encoded := make([]byte, 320)
		for i := range encoded {
			encoded[i] = byte(i)
		}
		got, err := s.audioPacket(encoded, now)
		if err != nil {
			t.Fatal(err)
		}
		// Upstream fixed its header Unix time independently of its local calendar.
		if full {
			h := c.crypt(got[:32], true)
			binary.LittleEndian.PutUint64(h[1:9], 1700000000)
			copy(got[:32], c.crypt(h, false))
		}
		sum := sha256.Sum256(got)
		if hex.EncodeToString(sum[:]) != want {
			t.Fatalf("audio fixture mismatch full=%v", full)
		}
	}
}

// reply headers authenticate status and negotiation fields, rather than a body.
func talkFakeReply(c *WireCodec, server net.Conn, kind, status, mask, full byte) error {
	var h [32]byte
	h[0] = kind
	h[11] = status
	h[12] = mask
	h[14] = full
	packet, err := c.EncodeCommand(h, nil)
	if err != nil {
		return err
	}
	return writeFull(server, packet)
}
func fakeTalkHandshake(c *WireCodec, server net.Conn, status, mask, full byte) error {
	return fakeTalkHandshakeReady(c, server, status, mask, full, true)
}
func fakeTalkHandshakeReady(c *WireCodec, server net.Conn, status, mask, full byte, ready bool) error {
	var setup [32]byte
	if _, err := io.ReadFull(server, setup[:]); err != nil {
		return err
	}
	if setup[0] != 0xa9 || setup[9] != 2 {
		return errors.New("bad talk setup")
	}
	setup[9] = 0
	setup[10] = 2
	setup[11] = 1
	if err := writeFull(server, setup[:]); err != nil {
		return err
	}
	p, err := c.ReadPacket(server)
	if err != nil {
		return err
	}
	if p.Type != 0x0b || binary.LittleEndian.Uint16(p.Header[13:15]) != 65535 || p.Header[15] != 0 {
		return errors.New("bad talk open")
	}
	size := int(binary.LittleEndian.Uint16(p.Header[11:13]))
	sum := sha256.Sum256(append(p.Header[:], p.Payload[:size]...))
	if !bytes.Equal(sum[:], p.Payload[size:size+32]) || string(p.Payload[:size]) != "viewer&&opaque&password/+==\x00OEM123\x000123456789abcdef\x00" {
		return errors.New("bad open SHA")
	}
	if err = talkFakeReply(c, server, 0x0b, status, mask, full); err != nil {
		return err
	}
	if status != 0 || mask&3 == 0 {
		return nil
	}
	for _, kind := range []byte{0x0c, 0x0d} {
		p, err = c.ReadPacket(server)
		if err != nil {
			return err
		}
		if p.Type != kind || p.Header[13] != 1 || binary.LittleEndian.Uint16(p.Header[11:13]) != 65535 {
			return errors.New("bad request")
		}
	}
	if !ready {
		return nil
	}
	return talkFakeReply(c, server, 0x0d, 0, 0, 0)
}
func TestTalkNegativeNegotiationAndCancellation(t *testing.T) {
	for _, tc := range []struct{ status, mask byte }{{2, 1}, {0, 0}} {
		client, server := net.Pipe()
		c := testCodec(t)
		done := make(chan error, 1)
		go func() { defer server.Close(); done <- fakeTalkHandshake(c, server, tc.status, tc.mask, 0) }()
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		s, err := openTalkConn(ctx, client, c, syntheticMediaCredentials(), 0, time.Hour)
		cancel()
		if err == nil {
			_ = s.Close()
			t.Fatal("accepted invalid negotiation")
		}
		if err = <-done; err != nil {
			t.Fatal(err)
		}
	}
	for _, stage := range []string{"setup", "ready", "frame", "frame-write"} {
		t.Run(stage, func(t *testing.T) {
			client, server := net.Pipe()
			defer server.Close()
			c := testCodec(t)
			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			done := make(chan error, 1)
			blocked := make(chan struct{})
			go func() {
				if stage == "setup" {
					close(blocked)
					return
				}
				if err := fakeTalkHandshakeReady(c, server, 0, 1, 0, stage != "ready"); err != nil {
					done <- err
					return
				}
				if stage == "frame" {
					_, err := c.ReadPacket(server)
					if err != nil {
						done <- err
						return
					}
				}
				close(blocked)
			}()
			result := make(chan error, 1)
			go func() {
				s, err := openTalkConn(ctx, client, c, syntheticMediaCredentials(), 0, time.Hour)
				if err == nil {
					defer s.Close()
					if stage == "frame" || stage == "frame-write" {
						err = s.WritePCM(make([]int16, 640))
					} else {
						_, err = s.readPacket()
					}
				}
				result <- err
			}()
			<-blocked
			cancel()
			select {
			case err := <-result:
				if err == nil {
					t.Fatal("cancellation ignored")
				}
			case <-time.After(time.Second):
				t.Fatal("cancellation blocked")
			}
		})
	}
}
func TestTalkMalformedPacketBoundsAndHash(t *testing.T) {
	c := testCodec(t)
	for _, kind := range []string{"length", "sha", "media", "type"} {
		t.Run(kind, func(t *testing.T) {
			client, server := net.Pipe()
			defer client.Close()
			defer server.Close()
			s := &TalkSession{conn: client, codec: c}
			var h [32]byte
			h[0] = 0x0b
			binary.LittleEndian.PutUint16(h[9:11], 32)
			switch kind {
			case "length":
				binary.LittleEndian.PutUint16(h[9:11], 4112)
			case "media":
				h[0] = 0xa2
				binary.LittleEndian.PutUint32(h[11:15], 65556)
			case "type":
				h[0] = 0x7f
			}
			wire := c.crypt(h[:], false)
			if kind == "sha" {
				wire = append(wire, c.crypt(make([]byte, 32), false)...)
			}
			go func() { _ = writeFull(server, wire) }()
			if _, err := s.readPacket(); err == nil {
				t.Fatal("accepted malformed talk packet")
			}
		})
	}
}

func TestTalkReadyRejectionClosesSession(t *testing.T) {
	client, server := net.Pipe()
	defer server.Close()
	c := testCodec(t)
	done := make(chan error, 1)
	go func() {
		if err := fakeTalkHandshakeReady(c, server, 0, 1, 0, false); err != nil {
			done <- err
			return
		}
		if err := talkFakeReply(c, server, 0x0d, 2, 0, 0); err != nil {
			done <- err
			return
		}
		var b [1]byte
		_, err := server.Read(b[:])
		if !errors.Is(err, io.EOF) {
			done <- errors.New("rejected session left open")
			return
		}
		done <- nil
	}()
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	s, err := openTalkConn(ctx, client, c, syntheticMediaCredentials(), 0, time.Hour)
	if err == nil {
		_ = s.Close()
		t.Fatal("accepted negative ready ACK")
	}
	if !strings.Contains(err.Error(), "status 2") {
		t.Fatal(err)
	}
	if err = <-done; err != nil {
		t.Fatal(err)
	}
}
